frase = 'Uma frase é qualquer conjunto de palavras que tem um sentido completo. Ela transmite uma ideia, um pedido ou um pensamento. Ela pode ter um verbo ou não, mas sempre termina com uma pausa forte na escrita.'
print("A frase tem", frase.count('a'), "letras 'a'.")
print("A primeira letra 'a' aparece na posição", frase.find('a') + 1)
print("A última letra 'a' aparece na posição", frase.rfind('a') + 1)